{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Bicuculline, a phthalide-isoquinoline alkaloid sharing the lactone and methylenedioxy features of noscapine, penetrated rat brain in a dose-dependent manner measured by LC-MS/MS, directly supporting meaningful CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Isocorydine, a related methoxy-substituted isoquinoline alkaloid with a tertiary amine, was detected in substantial amounts in rat brain within 10 minutes of administration, demonstrating effective BBB crossing for this alkaloid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tylocrebrine, a lipophilic methoxy-rich alkaloid, showed rapid brain accumulation with an AUCbrain of 2.1 µg·h/mL in mice, supporting meaningful CNS exposure for structurally related alkaloids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "(-)-Stepholidine, a tetrahydroprotoberberine with dimethoxyphenyl and tertiary amine features similar to noscapine, exhibited good brain penetration with a brain:plasma AUC ratio of about 0.7 in rat microdialysis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tetrahydroberberine, a close protoberberine analogue, was detected in rat CSF after administration, confirming that this alkaloid family can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Noscapine is predicted to have meaningful CNS access. Multiple structurally related isoquinoline and phthalide-isoquinoline alkaloids show direct brain or CSF penetration in rats and mice, including bicuculline, which shares the lactone-methylenedioxy core. The physicochemical profile (low MW, optimal logD, no HBD, high neutral fraction) is consistent with good passive BBB permeability, and no contradictory experimental evidence was identified.",
  "evidence_gaps": [
    "No direct noscapine-specific brain/plasma or CSF measurement was included in the supplied evidence.",
    "No explicit efflux-transporter data for noscapine were provided, although the high neutral fraction and related alkaloid evidence reduce this concern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

